from __future__ import absolute_import, division, print_function, with_statement

import collections
from json import JSONEncoder


# A JSONEncoder subclass which handles map-like and list-like objects.
class BuckJSONEncoder(JSONEncoder):
    def __init__(self):
        # TODO: Figure out why Python is such a special snowflake that it still
        # requires self vs super declaration mismatches between subclasses and superclasses.
        # Calling via `super(...).__init__(...)` vs calling `BuckJSONEncoder.__init__` or
        # `super(BuckJSONEncoder, self).__init__` all work in CPython for me locally,
        # but are fatal for either Python 3 on Windows or Python 3 on Mac, respectively.
        super(BuckJSONEncoder, self).__init__()

    def default(self, obj):
        if isinstance(obj, collections.Mapping) and isinstance(
            obj, collections.Sized
        ):  # nopep8
            return dict(obj)
        elif isinstance(obj, collections.Iterable) and isinstance(
            obj, collections.Sized
        ):
            return list(obj)
        else:
            return super(BuckJSONEncoder, self).default(obj)

