from functools import wraps
import json

def json_dialect_wrapper(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        req = args[0]
        if req.META['CONTENT_TYPE'].startswith("application/json"):
            req.data = json.loads(req.body.decode('utf-8'))
        return func(req)
    return wrapper

