    return_name = args.argopt('return', default_option='links').name

    # get the project
    project_filter = {'owner': user}
    if args.is_option_given(ungroup=True):
        filter_id_or_error = args.argopt('id', userinfo=user).filter_consumption_exception
        filter_id_or_error.po_name = '<todo>'         # need project_id return field? save convenience functions for later?
