    rr = r.table('projects').filter(project_filter).eq_join('owner', r.table('users'))
    rr = args.add_all_arg_options(rr)
    projs = list(rr.run(g.conn, time_format='raw'))
    if len(projs) == 0:
        return args.json_as_format_arg([])

    if len(projs) > 1:  # filter ok?
        return args.json_as_format_arg([])

    return args.json_as_format_arg(projos)

