from ..mcap import app
from ..decorators import apikey, jsonp
from flask import json
from .. import args
from .. import dbutil
from ..utils import error_response

@app.route('/v1.0/user/<user>/projects', methods=['GET'])
@apikey
@jsonp
def get_all_projects(user):
    rr = dbutil.get_project_table().filter({'owner': user})
    rr = args.add_all_arg_options(rr)
    items = list(rr.run(g.conn, time_format='raw'))
    return args.json_as_format_arg(items)

@app.route('/v1.0/user/<user>/projects/<project_id>/datafiles', methods=['GET'])
@apikey
@jsonp
def get_all_datafiles_for_project(user, project_id):
    dbutil.require_user_willis()
    dbutil.require_permission_to(user, 'projects', project_id)
    return dbutil.get_data_file_for_user_and_project(user, project_id)
